  };

  const offer = ctx.offer;
  const sections = [];

  if (ctx.company) {
    sections.push(`-- Fiche compte --\n${ctx.company.name} - secteur : ${ctx.company.sector || 'non renseigné'} (${ctx.company.lifecycle_status}) - ${truncate(ctx.company.description || '', 400)}`);
  }
  if (offer) {
    sections.push(`-- OFFRE CATALOGUE (ancrage obligatoire) --\n${offer.name} (practice ${offer.practice})\n${offer.short_description}\nLivrables types : ${(offer.typical_deliverables || []).join(', ')}\nCas d'usage : ${(offer.use_cases || []).join(', ')}`);
  }
  if (ctx.pricingGrid && ctx.pricingGrid.length) {
    const lines = ctx.pricingGrid.slice(0, 4).map(g => `${g.profile_name} (${g.seniority_level}) : ${g.tjm_min}-${g.tjm_max}${g.currency} (reco ${g.tjm_recommended})`);
    sections.push(`-- GRILLE TARIFAIRE (ordre de grandeur, jamais un prix ferme) --\n${lines.join('\n')}`);
  }
  if (ctx.deliveredPractices && ctx.deliveredPractices.length) {
    sections.push(`-- PRACTICES DÉJÀ LIVRÉES chez ce compte --\n${ctx.deliveredPractices.join(', ')}`);
  }
  if (ctx.suggestedPractices && ctx.suggestedPractices.length) {
    sections.push(`-- OFFRES SUGGÉRÉES (cross-sell possible) --\n${ctx.suggestedPractices.map(p => p.name).join(', ')}`);
  }
  if (ctx.anchorOpportunity) {
    sections.push(`-- Opportunité visée --\n${ctx.anchorOpportunity.need_summary || ctx.anchorOpportunity.title} - étape ${ctx.anchorOpportunity.stage}`);
  }
  if (ctx.anchorMission) {
    sections.push(`-- Mission en cours (ancrage cross-sell) --\n${ctx.anchorMission.title} - ${ctx.anchorMission.role_title || ''} depuis le ${ctx.anchorMission.start_date}`);
  } else if (ctx.activeMissions && ctx.activeMissions.length) {
    const lines = ctx.activeMissions.slice(0, 3).map(m => `${m.title} - ${m.role_title || ''} depuis le ${m.start_date}`);
    sections.push(`-- Missions en cours --\n${lines.join('\n')}`);
  }
  if (ctx.recentInteractions && ctx.recentInteractions.length) {
    const lines = ctx.recentInteractions.slice(0, 3).map(i => `${(i.occurred_at || '').slice(0,10)} - ${i.type} - ${truncate(i.summary || '', 150)}`);
    sections.push(`-- Historique commercial --\n${lines.join('\n')}`);
  }
  if (ctx.sectorIntelligence) {
    const fit = ctx.sectorIntelligence.practices_fit ? JSON.stringify(ctx.sectorIntelligence.practices_fit) : '';
    sections.push(`-- Intelligence sectorielle --\n${ctx.sectorIntelligence.name} - fit practices : ${fit}`);
  }
  if (ctx.sectorNews && ctx.sectorNews.length) {
    const lines = ctx.sectorNews.map(n => `${(n.published_at || '').slice(0,10)} - ${n.title}`);
    sections.push(`-- Signal/Actualité sectorielle --\n${lines.join('\n')}`);
  }
  if (ctx.previousPitches && ctx.previousPitches.length) {
    sections.push(`-- Pitchs précédents pour ce compte (ne pas répéter le même angle) --\n${ctx.previousPitches.length} pitch(s) déjà généré(s)`);
  }
  if (ctx.legacyPitches && ctx.legacyPitches.length) {
    sections.push(`-- Exemples de ton historiques (à imiter comme STYLE uniquement, jamais comme faits) --\n${truncate(JSON.stringify(ctx.legacyPitches), 500)}`);
  }
  if (ctx.scores) {
    sections.push(`-- Scores déterministes (calculés par Kredo, ne jamais recalculer) --\nConviction ${ctx.scores.conviction}/5 - Investissement ${ctx.scores.investment}/5`);
  }

  if (ctx.collaborator) {
    const c = ctx.collaborator;
    sections.push(`-- Profil consultant --\n${(ctx.person && ctx.person.fullName) || ''} - ${c.currentTitle || 'poste non renseigné'} - ${c.practice || 'practice non renseignée'} - séniorité ${c.seniority || 'non renseignée'} - statut ${c.status || 'non renseigné'}`);
  }
  if (ctx.currentMission) {
    sections.push(`-- Mission actuelle --\n${ctx.currentMission.title} - ${ctx.currentMission.roleTitle || ''} - statut ${ctx.currentMission.status || ''}`);
  }
  if (ctx.jobProfile) {
    sections.push(`-- Profil métier --\n${ctx.jobProfile.title || ''} - ${truncate(ctx.jobProfile.mainMission || '', 300)}`);
  }
  if (ctx.skills && ctx.skills.length) {
    sections.push(`-- Compétences --\n${ctx.skills.slice(0, 8).map(s => s.name).join(', ')}`);
  }
  if (ctx.managerProfile) {
    sections.push(`-- Manager --\n${ctx.managerProfile.fullName || ''}`);
  }
  if (ctx.internalRecipient) {
    const ir = ctx.internalRecipient;
    sections.push(`-- Destinataire interne --\nRôle : ${ir.role || 'non renseigné'} - Relation : ${ir.relationship || 'non renseignée'} - Domaine : ${ir.domain || 'non renseigné'}`);
  }

  const contextBlock = sections.join('\n\n');
  // ADR-0013 Lot 3 — outputKind/activityCategory pilotent le choix du system
  // prompt (déjà calculés avec fallback par Validate Brief). Le fallback final
  // (SYSTEM_PROMPT_MEETING_BRIEFING) couvre commerce_prospection/commerce_actif
  // ET les runs antérieurs au Lot 2 sans activityCategory — comportement
  // strictement identique à avant ce lot pour ces cas.
  const isSpoken = outputKind === 'spoken_pitch';
  let systemPrompt;
  if (isSpoken) {
    systemPrompt = SYSTEM_PROMPT_SPOKEN_PITCH;
  } else if (activityCategory === 'delivery') {
    systemPrompt = SYSTEM_PROMPT_BRIEFING_DELIVERY;
  } else if (activityCategory === 'management_consultants' || activityCategory === 'internal_staff') {
    systemPrompt = SYSTEM_PROMPT_BRIEFING_MANAGEMENT;
  } else if (activityCategory === 'recrutement') {
    systemPrompt = SYSTEM_PROMPT_BRIEFING_RECRUITMENT;
  } else {
    systemPrompt = SYSTEM_PROMPT_MEETING_BRIEFING;
  }

  const userPrompt = `${PITCH_SCENARIO_MISSIONS[scenario] || ''}

ÉMETTEUR :
${senderName}${sender.practice ? ' - practice ' + sender.practice : ''}

DESTINATAIRE :
${recipientContextLine || `${recipient.displayName || 'Non renseigné'} - ${recipient.persona || ''} chez ${recipient.companyName || (ctx.company && ctx.company.name) || ''}
Relation : ${recipient.relation || ''}`}

TON :
${toneInstruction}

CONTEXTE DISPONIBLE :
${contextBlock || '(contexte limité)'}

INSTRUCTIONS IMPÉRATIVES DE L'UTILISATEUR :
${(brief.context && brief.context.mustInclude) || '(aucune)'}`;

  return [{
    json: {
      ...briefData,
      resolvedContext: ctx,
      systemPrompt,
      userPrompt,
    }
  }];
}

