}
if (ctx.managerProfile) {
  sections.push(`-- Manager --\n${ctx.managerProfile.fullName || ''}`);
}
if (ctx.internalRecipient) {
  const ir = ctx.internalRecipient;
  sections.push(`-- Destinataire interne --\nRôle : ${ir.role || 'non renseigné'} - Relation : ${ir.relationship || 'non renseignée'} - Domaine : ${ir.domain || 'non renseigné'}`);
}

let contextBlock = sections.join('\n\n');
const MAX_CONTEXT_CHARS = 8000;
if (contextBlock.length > MAX_CONTEXT_CHARS) {
  const priorityOrder = ['-- Communications précédentes --', '-- Intelligence sectorielle --', '-- Historique commercial --'];
  for (const marker of priorityOrder) {
    if (contextBlock.length <= MAX_CONTEXT_CHARS) break;
    const idx = sections.findIndex(s => s.startsWith(marker));
    if (idx >= 0) sections.splice(idx, 1);
    contextBlock = sections.join('\n\n');
  }
  contextBlock = truncate(contextBlock, MAX_CONTEXT_CHARS);
}

const userPrompt = `${SCENARIO_MISSIONS[scenario] || ''}

ÉMETTEUR :
Nom : ${senderName}
Rôle : ${sender.role || senderProfile.role || ''}
${sender.practice ? `Practice : ${sender.practice}` : ''}
Entreprise : Kredo Digital — ESN premium spécialisée en Data/IA, Cloud, Product Management et Cybersécurité

DESTINATAIRE :
${recipientContextLine || `Nom : ${recipient.displayName || 'Non renseigné'}
Fonction : ${recipient.persona || ''}
Entreprise : ${recipient.companyName || (ctx.company && ctx.company.name) || ''}
Type de relation : ${recipient.relation || ''}`}

OBJECTIF DU MESSAGE :
${brief.who.objective || ''}

STYLE :
Canal : ${brief.what.channel}
Ton : ${toneInstruction}
Langue : ${brief.how.language === 'en' ? 'Anglais' : 'Français'}
Formalité : ${brief.how.formality}
Longueur : ${LENGTH_RANGES[brief.what.length] || LENGTH_RANGES.standard}

CONTEXTE DISPONIBLE :
${contextBlock || '(contexte limité — nouveau prospect ou compte peu renseigné)'}

INSTRUCTIONS IMPÉRATIVES DE L'UTILISATEUR :
${(brief.context && brief.context.mustInclude) || '(aucune)'}

EXCLUSIONS :
${(brief.context && brief.context.mustExclude) || '(aucune)'}`;

return [{
  json: {
    ...briefData,
    resolvedContext: ctx,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt: userPrompt,
  }
}];

