parameters.jsCode:
const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = upstream.isPitch
    ? { kind: null, warnings: ['output_not_json'] }
    : { subjects: [], body: content, key_points: [], source_refs: [], warnings: ['output_not_json'] };
}

if (upstream.isPitch) {
  // ADR-0013 Lot 3 — outputKind (déjà calculé avec fallback par Validate Brief)
  // remplace la déduction par channel.
  const isSpoken = upstream.outputKind === 'spoken_pitch';
  const expectedKind = isSpoken ? 'spoken_pitch' : 'meeting_briefing';
  if (parsed.kind !== expectedKind) {
    throw new Error(`Sortie pitch invalide : kind attendu "${expectedKind}", reçu "${parsed.kind}"`);
  }
  if (isSpoken) {
    if (!parsed.hook || !parsed.ask) {
      throw new Error('Pitch oral incomplet : hook et ask sont requis');
    }
  } else {
    if (!parsed.objective || !parsed.key_message || !Array.isArray(parsed.arguments) || parsed.arguments.length === 0) {
      throw new Error('Fiche de préparation incomplète : objective, key_message et arguments sont requis');
    }
    // ADR-0013 Lot 3 — les 3 catégories non commerciales (delivery/interne_
    // management/recrutement) exigent postures/emotional_context/power_dynamic
    // (imposé par leur system prompt respectif). Les catégories commerciales
    // existantes (commerce_prospection/commerce_actif) n'ont jamais eu ces
    // champs — non-régression : validation conditionnelle à activityCategory.
    const NON_COMMERCIAL_CATEGORIES = ['delivery', 'management_consultants', 'internal_staff', 'recrutement'];
    if (NON_COMMERCIAL_CATEGORIES.includes(upstream.activityCategory)) {
      if (!parsed.emotional_context || !parsed.power_dynamic) {
        throw new Error('Briefing non commercial incomplet : emotional_context et power_dynamic sont requis');
      }
    }
  }
} else {
  if (!parsed.body || parsed.body.length < 20) {
    throw new Error('Le corps généré est vide ou trop court');
  }
}

return [{
  json: {
    ...upstream,
    generatedOutput: parsed,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

const data = $input.first().json;
const brief = data.brief;
const output = data.generatedOutput;
const qaFlags = [];

if (data.isPitch) {
  // ADR-0013 Lot 3 — outputKind remplace la déduction par channel.
  const isSpoken = data.outputKind === 'spoken_pitch';
  const fullText = isSpoken
    ? [output.hook, output.problem_recognition, output.offer_link, output.ask, output.alt_close].filter(Boolean).join(' ')
    : [output.objective, output.key_message, ...(output.arguments || []).map(a => `${a.title} ${a.evidence}`), ...(output.expected_objections || []).map(o => `${o.objection} ${o.response}`), ...(output.data_points_to_mention || []), ...(output.close_options || [])].filter(Boolean).join(' ');

  // ADR-0013 D-5 — has_offer_ref n'a de sens que si une offre a réellement été
  // fournie en contexte (offerRef présent). Avant ce lot, ce check tournait
  // pour tout canal pitch et échouait systématiquement "À vérifier" pour les
  // scénarios sans offre — trompeur pour les nouveaux scénarios non commerciaux.
  if (data.offerRef) {
    const offerName = (data.resolvedContext && data.resolvedContext.offer && data.resolvedContext.offer.name) || null;
    const offerMentioned = offerName ? fullText.toLowerCase().includes(offerName.toLowerCase().split(',')[0].trim()) : false;
    const hasOfferRef = !!offerName && (offerMentioned || !!output.offer_link);
    qaFlags.push({ check: 'has_offer_ref', passed: hasOfferRef, detail: offerName ? `Offre attendue : ${offerName}` : 'Offre référencée introuvable dans le contexte résolu' });
  }

  if (isSpoken) {
    const wordCount = fullText.split(/\s+/).filter(Boolean).length;
    const inTarget = wordCount >= 60 && wordCount <= 130;
    qaFlags.push({ check: 'word_count_in_target', passed: inTarget, detail: `${wordCount} mots (cible 80-100)` });
    qaFlags.push({ check: 'has_call_to_action', passed: !!(output.ask && output.ask.trim().length > 0), detail: output.ask ? 'ask présent' : 'ask manquant' });
  } else {
    const allHaveEvidence = Array.isArray(output.arguments) && output.arguments.length > 0 && output.arguments.every(a => a.evidence && a.evidence.trim().length > 0);
    qaFlags.push({ check: 'arguments_have_evidence', passed: allHaveEvidence, detail: allHaveEvidence ? 'ok' : 'un argument sans evidence' });
    qaFlags.push({ check: 'has_call_to_action', passed: Array.isArray(output.close_options) && output.close_options.length > 0, detail: 'close_options' });
  }

  // ADR-0013 Lot 3 — QA renforcé : les catégories non commerciales ne doivent
  // jamais dériver vers un discours de vente (garde-fou défense-en-profondeur,
  // en complément de la règle déjà posée dans les 3 nouveaux system prompts).
  const NON_COMMERCIAL_CATEGORIES = ['delivery', 'management_consultants', 'internal_staff', 'recrutement'];
  if (NON_COMMERCIAL_CATEGORIES.includes(data.activityCategory)) {
    const commercialTerms = /catalogue kredo|grille tarifaire|tjm\b|offre commerciale|proposition commerciale/i;
    const hasCommercialLanguage = commercialTerms.test(fullText);
    qaFlags.push({
      check: 'no_commercial_language',
      passed: !hasCommercialLanguage,
      detail: hasCommercialLanguage ? 'Vocabulaire commercial détecté dans un briefing non commercial' : 'ok',
    });
  }

  const normalizeAccents = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const priceCommitmentPattern = /\d{2,4}\s?€/;
  const softeners = /a partir de|environ|selon profil|suivant profil|entre|de l'ordre de|ordre de grandeur/i;
  const normalizedText = normalizeAccents(fullText);
  const hasPriceNumbers = priceCommitmentPattern.test(fullText);
  const hasSoftener = softeners.test(normalizedText);
  qaFlags.push({
    check: 'no_price_commitment',
    passed: !hasPriceNumbers || hasSoftener,
    detail: hasPriceNumbers && !hasSoftener ? "Montant cité sans formulation d'ordre de grandeur" : 'ok',
  });

  return [{ json: { ...data, qaFlags } }];
}

const body = output.body;

const wordCount = body.split(/\s+/).filter(Boolean).length;
const limits = {
  ultra_short: [30, 100],
  concise: [60, 170],
  standard: [120, 270],
  detailed: [180, 500],
};
const range = limits[brief.what.length] || [60, 300];
const min = range[0], max = range[1];
if (wordCount < min || wordCount > max) {
  qaFlags.push({ check: 'length', passed: false, detail: `${wordCount} mots (attendu ${min}-${max})` });
} else {
  qaFlags.push({ check: 'length', passed: true, detail: `${wordCount} mots` });
}

if (brief.how.formality === 'vous' && /\btu\b|\bt'|\bton\b|\bta\b|\btes\b/i.test(body)) {
  qaFlags.push({ check: 'formality', passed: false, detail: 'Tutoiement détecté malgré vouvoiement demandé' });
}

if (brief.context && brief.context.mustExclude) {
  const excluded = brief.context.mustExclude.toLowerCase().split(/[,;\n]/).map(s => s.trim()).filter(Boolean);
  for (const term of excluded) {
    if (term && body.toLowerCase().includes(term)) {
      qaFlags.push({ check: 'exclusion', passed: false, detail: `Terme exclu présent : "${term}"` });
    }
  }
}

if (brief.who.recipient.displayName) {
  const lastName = brief.who.recipient.displayName.split(' ').pop();
  if (lastName && !body.includes(lastName)) {
    qaFlags.push({ check: 'recipient_name', passed: false, detail: 'Nom du destinataire absent du message' });
  }
}

const ctaPatterns = /rendez-vous|rencontrer|échanger|appel|disponible|créneau|discuter|meeting|call/i;
if (!ctaPatterns.test(body)) {
  qaFlags.push({ check: 'cta_present', passed: false, detail: "Aucun appel à l'action détecté" });
}

return [{
  json: {
    ...data,
    qaFlags,
  }
}];

const data = $input.first().json;
const output = data.generatedOutput;

// ADR-0013 Lot 3 — 3e result_type "prise_de_parole" pour les briefings/pitchs
// non commerciaux (delivery/interne_management/recrutement), distinct de
// commercial_pitch (auto-sauvegarde documentaire existante, catégorisation
// séparée — voir mapResultTypeToDocumentType côté front, Lot 3 également).
const COMMERCIAL_CATEGORIES = ['commerce_prospection', 'commerce_actif'];
const resultType = !data.isPitch
  ? 'communication'
  : COMMERCIAL_CATEGORIES.includes(data.activityCategory)
    ? 'commercial_pitch'
    : 'prise_de_parole';

// Titre concis dérivé du brief (type + objectif), jamais de la phrase générée —
// un pitch affiché avec sa propre accroche en guise de titre est illisible dans
// les listes/dialogs (bug remonté après premier test réel).
const PITCH_CHANNEL_LABELS = {
  spoken_pitch_30s: 'Pitch 30 s',
  meeting_briefing: 'Fiche de préparation RDV',
};
const PITCH_OBJECTIVE_LABELS = {
  get_meeting: 'Obtenir un rendez-vous',
  get_reply: 'Obtenir une réponse',
  present_offer: 'Présenter une offre',
  accelerate_decision: 'Accélérer une décision',
  summarize_decisions: 'Synthétiser décisions et actions',
  escalate_issue: 'Escalader un sujet',
  align_internal: 'Aligner en interne',
  secure_resources: 'Obtenir des moyens',
  deliver_difficult_news: 'Annoncer une nouvelle difficile',
  address_performance_issue: 'Adresser un problème de performance',
  close_candidate: 'Closer un candidat',
  advocate_for_candidate: 'Défendre un candidat',
  negotiate_terms: 'Négocier les conditions',
  submit_profile: 'Positionner un profil',
};

function buildPitchTitle(brief) {
  const channelLabel = PITCH_CHANNEL_LABELS[brief.what.channel] || brief.what.channel;
  const objective = brief.who && brief.who.objective;
  const objectiveLabel = objective ? (PITCH_OBJECTIVE_LABELS[objective] || objective) : null;
  return objectiveLabel ? `${channelLabel} — ${objectiveLabel}` : channelLabel;
}

const title = data.isPitch
  ? buildPitchTitle(data.brief)
  : ((output.subjects && output.subjects[0]) || null);

const callbackBody = {
  runId: data.runId,
  phase: 5,
  resultType: resultType,
  status: 'succeeded',
  contentJson: output,
  title: title,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.resolvedContext || null,
  sourceRefs: (output.source_refs || []).map(s => ({ entityType: 'context', label: s })),
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;
let resultType = 'communication';

try {
  const vb = $('Validate Brief').item.json;
  runId = vb.runId || null;
  callbackUrl = vb.callbackUrl || null;
  resultType = vb.isPitch ? 'commercial_pitch' : 'communication';
} catch (e) {
  // Validate Brief n'a produit aucune sortie exploitable (ex: signature invalide
  // avant extraction des champs) — on ne peut pas notifier de façon fiable.
}

let errorMessage = 'Erreur inconnue dans le workflow intel-020-communication';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  runId,
  phase: 5,
  resultType,
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
